 entry RECORD; snapshot TEXT; document JSONB; item JSONB; group_item JSONB; selection JSONB;
 source_item JSONB; baseline_bullets JSONB; role JSONB; cv JSONB; defaults JSONB; chosen JSONB; field TEXT;
 idx INTEGER; source_idx INTEGER; target TEXT[]; key TEXT;
 next_draft JSONB; next_published JSONB;
BEGIN
 FOR entry IN SELECT * FROM "Content" WHERE "locale" IN ('en','vi') FOR UPDATE LOOP
  next_draft:=entry."draft";next_published:=entry."published";role:=payload->entry."locale";
  FOREACH snapshot IN ARRAY ARRAY['draft','published'] LOOP
   document:=CASE WHEN snapshot='draft' THEN next_draft ELSE next_published END;
   IF document IS NULL OR document='null'::JSONB THEN CONTINUE; END IF;
   -- Derive stable initial IDs from the actual snapshot; never replace its fact text.
   FOR item,idx IN SELECT value,(ordinality-1)::INTEGER FROM jsonb_array_elements(document->'experience') WITH ORDINALITY LOOP
    IF NOT item ? 'bullets' OR item->'bullets'='[]'::JSONB THEN
     SELECT COALESCE(jsonb_agg(jsonb_build_object('id','bullet-'||ordinality::TEXT,'text',value) ORDER BY ordinality),'[]'::JSONB)
      INTO chosen FROM jsonb_array_elements(COALESCE(item->'highlights','[]'::JSONB)) WITH ORDINALITY;
     document:=jsonb_set(document,ARRAY['experience',idx::TEXT,'bullets'],chosen,true);
    END IF;
   END LOOP;
   FOR group_item IN SELECT value FROM jsonb_array_elements(role->'skills') LOOP
    IF NOT EXISTS (SELECT 1 FROM jsonb_array_elements(document->'skills') e WHERE e->>'id'=group_item->>'id') THEN
     SELECT COALESCE(jsonb_agg(w.value ORDER BY w.ordinality),'[]'::JSONB) INTO chosen FROM jsonb_array_elements(group_item->'projectIds') WITH ORDINALITY w
      WHERE EXISTS(SELECT 1 FROM jsonb_array_elements(document->'projects') p WHERE p->'id'=w.value);
     group_item:=jsonb_set(group_item,'{projectIds}',chosen);
     document:=jsonb_set(document,'{skills}',document->'skills'||jsonb_build_array(group_item),false);
    END IF;
   END LOOP;
   IF NOT document->'settings' ? 'websiteSkillIds' THEN
    document:=jsonb_set(document,'{settings,websiteSkillIds}',role->'websiteSkillIds',true);
   END IF;
   IF NOT document->'settings' ? 'experienceNote' THEN
    document:=jsonb_set(document,'{settings,experienceNote}',role->'experienceNote',true);
   END IF;
   -- Split research from applied client/tool experience only for the original skill list.
   SELECT (ordinality-1)::INTEGER INTO source_idx FROM jsonb_array_elements(document->'skills') WITH ORDINALITY WHERE value->>'id'='ai-development-tools' LIMIT 1;
   IF source_idx IS NOT NULL AND document #> ARRAY['skills',source_idx::TEXT,'items'] = '["Claude Code","Codex","Google Antigravity","Prompt engineering research","Multi-agent workflow research"]'::JSONB THEN
    document:=jsonb_set(document,ARRAY['skills',source_idx::TEXT,'items'],'["Claude Code","Codex","Google Antigravity"]'::JSONB);
   END IF;
   FOR cv,idx IN SELECT value,(ordinality-1)::INTEGER FROM jsonb_array_elements(document->'cvs') WITH ORDINALITY LOOP
    defaults:=CASE cv->>'id' WHEN 'ai-engineer' THEN role->'ai' WHEN 'senior-software-engineer' THEN role->'senior' ELSE NULL END;
    IF defaults IS NULL THEN CONTINUE; END IF;
    IF cv->>'id'='senior-software-engineer' AND role->'oldSeniorSummaries' @> jsonb_build_array(cv->'summary') THEN
     cv:=jsonb_set(cv,'{summary}',defaults->'summary');
    END IF;
    FOREACH field IN ARRAY ARRAY['sectionOrder','projectsHeading'] LOOP
     IF NOT cv ? field THEN cv:=jsonb_set(cv,ARRAY[field],defaults->field,true); END IF;
    END LOOP;
    IF NOT cv ? 'experienceSelections' THEN
     selection:='{}'::JSONB;
     FOR key,chosen IN SELECT * FROM jsonb_each(defaults->'experienceSelections') LOOP
      SELECT value INTO source_item FROM jsonb_array_elements(document->'experience') WHERE value->>'id'=key LIMIT 1;
      SELECT COALESCE(jsonb_agg(jsonb_build_object('id','bullet-'||ordinality::TEXT,'text',value) ORDER BY ordinality),'[]'::JSONB)
       INTO baseline_bullets FROM jsonb_array_elements(COALESCE(payload->'experienceBaseline'->key,'[]'::JSONB)) WITH ORDINALITY;
      -- Customize views only for unchanged source facts/IDs. Custom experience defaults to its complete text.
      IF source_item->'highlights'=payload->'experienceBaseline'->key AND source_item->'bullets'=baseline_bullets AND NOT EXISTS (
       SELECT 1 FROM jsonb_array_elements(chosen) requested WHERE NOT EXISTS (
        SELECT 1 FROM jsonb_array_elements(source_item->'bullets') b WHERE b->'id'=requested
       )
      ) THEN selection:=selection||jsonb_build_object(key,chosen); END IF;
     END LOOP;
     cv:=jsonb_set(cv,'{experienceSelections}',selection,true);
    END IF;
    chosen:=CASE cv->>'id' WHEN 'ai-engineer' THEN role->'oldAiSkillIds' ELSE role->'oldSeniorSkillIds' END;
    IF cv->'skillIds'=chosen THEN
     SELECT COALESCE(jsonb_agg(w.value ORDER BY w.ordinality),'[]'::JSONB) INTO chosen FROM jsonb_array_elements(defaults->'skillIds') WITH ORDINALITY w
      WHERE EXISTS(SELECT 1 FROM jsonb_array_elements(document->'skills') s WHERE s->'id'=w.value);
     cv:=jsonb_set(cv,'{skillIds}',chosen);
    END IF;
    document:=jsonb_set(document,ARRAY['cvs',idx::TEXT],cv,false);
   END LOOP;
   IF snapshot='draft' THEN next_draft:=document;ELSE next_published:=document;END IF;
  END LOOP;
  IF next_draft IS DISTINCT FROM entry."draft" OR next_published IS DISTINCT FROM entry."published" THEN
   UPDATE "Content" SET "draft"=next_draft,"published"=next_published,"revision"="revision"+1,"updatedAt"=CURRENT_TIMESTAMP,
    "publishedAt"=CASE WHEN next_published IS DISTINCT FROM entry."published" THEN CURRENT_TIMESTAMP ELSE entry."publishedAt" END WHERE "locale"=entry."locale";
  END IF;
 END LOOP;
END $migration$;
